import type { CSSProperties } from "react";
import { ICONS } from "./icons.generated";

/**
 * Phosphor Bold by kebab-case name (the design writes `ph-<name>`). Renders the icon's bold paths inline
 * (registry generated by scripts/gen-icons.mjs), so only one weight ships and it works in server and
 * client components alike. Decorative unless `label` is set.
 */
export function Icon({
  name,
  size = 20,
  className,
  style,
  label,
}: {
  name: string;
  size?: number;
  className?: string;
  style?: CSSProperties;
  label?: string;
}) {
  const markup = ICONS[name.replace(/^ph-/, "")] ?? ICONS["question"];
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 256 256"
      fill="currentColor"
      className={className}
      style={{ flex: "none", ...style }}
      aria-hidden={label ? undefined : true}
      aria-label={label}
      role={label ? "img" : undefined}
      focusable="false"
      dangerouslySetInnerHTML={{ __html: markup }}
    />
  );
}
